#include "crashpad/store.h"
#include "crashpad/pager.h"
#include <assert.h>
#include <stdio.h>
#include <pthread.h>
#include <stdlib.h>
#include <string.h>
#ifdef _WIN32
#include <process.h>
#define CP_TEST_PID _getpid()
#else
#include <unistd.h>
#define CP_TEST_PID getpid()
#endif
#undef assert
#define assert(condition) do { if (!(condition)) { fprintf(stderr,"CHECK failed: %s (%s:%d)\n",#condition,__FILE__,__LINE__); abort(); } } while (0)
static int count_cb(uint64_t k,uint64_t v,void*p){(void)k;(void)v;(*(size_t*)p)++;return 1;}
typedef struct {cp_blockdev*inner;int fail_write_at,writes,fail_sync,syncs;} fail_dev_ctx;
static cp_status fail_read(cp_blockdev*d,uint64_t o,void*b,size_t n){return cp_dev_read(((fail_dev_ctx*)d->ctx)->inner,o,b,n);}
static cp_status fail_write(cp_blockdev*d,uint64_t o,const void*b,size_t n){fail_dev_ctx*c=d->ctx;c->writes++;if(c->fail_write_at==c->writes)return CP_E_IO;return cp_dev_write(c->inner,o,b,n);}
static cp_status fail_sync(cp_blockdev*d){fail_dev_ctx*c=d->ctx;c->syncs++;if(c->fail_sync==c->syncs)return CP_E_IO;return cp_dev_sync(c->inner);}
static cp_status fail_size(cp_blockdev*d,uint64_t*out){return cp_dev_size(((fail_dev_ctx*)d->ctx)->inner,out);}
static void fail_close(cp_blockdev*d){(void)d;}
static const cp_blockdev_ops fail_ops={fail_read,fail_write,fail_sync,fail_size,fail_close};
static void test_wal_io_failures(void){for(int failure=1;failure<=3;failure++){cp_sim_dev*sim;cp_blockdev*inner;assert(cp_sim_dev_create(16u*1024u*1024u,&sim,&inner)==CP_OK);fail_dev_ctx ctx={inner,0,0,0,0};cp_blockdev wrapped={&fail_ops,&ctx};cp_store*s;assert(cp_store_open(&wrapped,4,&s)==CP_OK);if(failure==1)ctx.fail_write_at=1;else if(failure==2)ctx.fail_write_at=2;else ctx.fail_sync=1;assert(cp_store_put(s,41,410)==CP_E_IO);assert(cp_store_put(s,42,420)==CP_E_IO);ctx.fail_write_at=0;ctx.fail_sync=0;assert(cp_store_recover(s)==CP_OK);uint64_t value=0;cp_status found=cp_store_get(s,41,&value);assert(found==CP_OK||found==CP_E_RANGE);assert(cp_store_put(s,42,420)==CP_OK);assert(cp_store_get(s,42,&value)==CP_OK&&value==420);cp_store_close(s);assert(cp_store_open(&wrapped,4,&s)==CP_OK);assert(cp_store_get(s,42,&value)==CP_OK&&value==420);cp_store_close(s);cp_sim_dev_destroy(sim);cp_dev_close(inner);}}
typedef struct {cp_coordinator*c;uint64_t start;cp_status status;} writer_arg;
static void*writer_thread(void*context){writer_arg*a=context;a->status=CP_OK;for(uint64_t i=0;i<16;i++)if(cp_coordinator_put(a->c,a->start+i,a->start+i*3)!=CP_OK){a->status=CP_E_IO;break;}return NULL;}
static cp_status flush_lsn(void*ctx,uint64_t lsn){uint64_t*last=ctx;if(lsn>*last)*last=lsn;return CP_OK;}
static void test_buffer_pool(void){cp_sim_dev*sim;cp_blockdev*d;cp_buffer_pool*p;cp_page*page;uint64_t flushed=0;assert(cp_sim_dev_create(64*1024,&sim,&d)==CP_OK);assert(cp_buffer_pool_create(d,1,flush_lsn,&flushed,&p)==CP_OK);assert(cp_buffer_pool_new(p,1,CP_PAGE_BTREE_LEAF,&page)==CP_OK);uint64_t value=88;assert(cp_page_insert_cell(page,0,&value,sizeof value)==CP_OK);assert(cp_buffer_pool_mark_dirty(p,1,4)==CP_OK);assert(cp_buffer_pool_new(p,2,CP_PAGE_BTREE_LEAF,&page)==CP_E_BUSY);assert(cp_buffer_pool_flush(p)==CP_E_BUSY);assert(cp_buffer_pool_unpin(p,1)==CP_OK);assert(cp_buffer_pool_flush(p)==CP_OK&&flushed==4);assert(cp_buffer_pool_fetch(p,1,&page)==CP_OK);const void*cell;uint16_t len;assert(cp_page_get_cell(page,0,&cell,&len)==CP_OK&&len==sizeof value&&*(const uint64_t*)cell==value);assert(cp_buffer_pool_unpin(p,1)==CP_OK);cp_buffer_pool_destroy(p);cp_sim_dev_destroy(sim);cp_dev_close(d);}
static void test_page(void){cp_page p;cp_page_init(&p,7,CP_PAGE_BTREE_LEAF);uint64_t a=11,b=22;assert(cp_page_insert_cell(&p,0,&a,sizeof a)==CP_OK);assert(cp_page_insert_cell(&p,1,&b,sizeof b)==CP_OK);assert(cp_page_delete_cell(&p,0)==CP_OK);cp_page_compact(&p);cp_page_seal(&p);cp_status verified=cp_page_verify(&p,7);if(verified!=CP_OK){const cp_page_header*h=cp_page_chdr(&p);const cp_slot*s=(const cp_slot*)(p.bytes+CP_PAGE_HEADER_SIZE);cp_page copy=p;uint32_t stored=h->checksum;cp_page_hdr(&copy)->checksum=0;fprintf(stderr,"page debug: verify=%d crc=%x stored=%x magic=%x version=%u type=%u id=%llu lower=%u upper=%u n=%u slot=(%u,%u)\n",verified,cp_crc32c(copy.bytes,CP_PAGE_SIZE,0),stored,h->magic,h->version,h->type,(unsigned long long)h->page_id,h->free_lower,h->free_upper,h->nslots,s->off,s->len);}assert(verified==CP_OK);const void*x;uint16_t n;assert(cp_page_get_cell(&p,0,&x,&n)==CP_OK&&n==8&&*(const uint64_t*)x==22);p.bytes[200]^=1;assert(cp_page_verify(&p,7)==CP_E_CORRUPT);cp_page_init(&p,8,CP_PAGE_BTREE_LEAF);unsigned char byte=0;assert(cp_page_insert_cell(&p,0,&byte,UINT16_MAX)==CP_E_RANGE);unsigned char full[CP_PAGE_SIZE]={0};assert(cp_page_insert_cell(&p,0,full,(uint16_t)(CP_PAGE_SIZE-CP_PAGE_HEADER_SIZE-sizeof(cp_slot)))==CP_OK);cp_page_seal(&p);assert(cp_page_verify(&p,8)==CP_OK);cp_page_init(&p,9,CP_PAGE_BTREE_LEAF);assert(cp_page_insert_cell(&p,0,&a,sizeof a)==CP_OK);assert(cp_page_insert_cell(&p,1,&b,sizeof b)==CP_OK);cp_slot first=*(cp_slot*)(p.bytes+CP_PAGE_HEADER_SIZE);*(cp_slot*)(p.bytes+CP_PAGE_HEADER_SIZE+sizeof(cp_slot))=first;cp_page_seal(&p);assert(cp_page_verify(&p,9)==CP_E_CORRUPT);cp_page_compact(&p);}
static void test_tree_wal(void){cp_sim_dev*sim;cp_blockdev*d;uint64_t oracle[1000];assert(cp_sim_dev_create(16u*1024u*1024u,&sim,&d)==CP_OK);cp_store*s;assert(cp_store_open(d,8,&s)==CP_OK);for(uint64_t i=0;i<1000;i++){uint64_t key=(i*7919)%1000,value=i+10;oracle[key]=value;assert(cp_store_put(s,key,value)==CP_OK);}for(uint64_t key=0;key<1000;key++){uint64_t v;assert(cp_store_get(s,key,&v)==CP_OK);assert(v==oracle[key]);}size_t n=0;assert(cp_store_scan(s,200,299,count_cb,&n)==CP_OK&&n==100);assert(cp_store_checkpoint(s)==CP_OK);assert(cp_store_put(s,1001,7001)==CP_OK);cp_store_close(s);assert(cp_store_open(d,8,&s)==CP_OK);assert(cp_store_operation_count(s)==1001);uint64_t v;assert(cp_store_get(s,501,&v)==CP_OK&&v==oracle[501]);assert(cp_store_get(s,1001,&v)==CP_OK&&v==7001);assert(cp_store_recover(s)==CP_OK);assert(cp_store_get(s,1001,&v)==CP_OK&&v==7001);cp_store_close(s);cp_sim_dev_destroy(sim);cp_dev_close(d);}
static void test_tree_boundaries_and_updates(void){cp_sim_dev*sim;cp_blockdev*d;cp_store*s;assert(cp_sim_dev_create(16u*1024u*1024u,&sim,&d)==CP_OK);assert(cp_store_open(d,8,&s)==CP_OK);uint64_t keys[]={UINT64_MAX,0,UINT64_MAX-1,1,UINT64_C(1)<<63,31,32,33};for(size_t i=0;i<sizeof keys/sizeof keys[0];i++)assert(cp_store_put(s,keys[i],i)==CP_OK);for(uint64_t i=0;i<40;i++)assert(cp_store_put(s,32,i+1000)==CP_OK);uint64_t v;assert(cp_store_get(s,32,&v)==CP_OK&&v==1039);size_t n=0;assert(cp_store_scan(s,31,33,count_cb,&n)==CP_OK&&n==3);assert(cp_store_checkpoint(s)==CP_OK);assert(cp_store_recover(s)==CP_OK);assert(cp_store_get(s,UINT64_MAX,&v)==CP_OK&&v==0);assert(cp_store_get(s,UINT64_MAX-1,&v)==CP_OK&&v==2);assert(cp_store_get(s,32,&v)==CP_OK&&v==1039);cp_store_close(s);cp_sim_dev_destroy(sim);cp_dev_close(d);}
static void test_file_persistence(void){const char*path="test-store-persistence.db";remove(path);cp_blockdev*d;cp_store*s;assert(cp_file_dev_open(path,1,&d)==CP_OK);assert(cp_store_open(d,4,&s)==CP_OK);assert(cp_store_put(s,123,456)==CP_OK);assert(cp_store_checkpoint(s)==CP_OK);assert(cp_store_put(s,124,457)==CP_OK);cp_store_close(s);cp_dev_close(d);assert(cp_file_dev_open(path,0,&d)==CP_OK);assert(cp_store_open(d,4,&s)==CP_OK);uint64_t v;assert(cp_store_get(s,123,&v)==CP_OK&&v==456);assert(cp_store_get(s,124,&v)==CP_OK&&v==457);cp_store_close(s);cp_dev_close(d);remove(path);}
static void test_coordinator_storage(void){char dir[80];snprintf(dir,sizeof dir,"coordinator-test-%ld",(long)CP_TEST_PID);cp_coordinator*c;assert(cp_coordinator_open(dir,4,8,&c)==CP_OK);pthread_t threads[4];writer_arg args[4];for(size_t i=0;i<4;i++){args[i]=(writer_arg){c,i*16,CP_OK};assert(pthread_create(&threads[i],NULL,writer_thread,&args[i])==0);}for(size_t i=0;i<4;i++){assert(pthread_join(threads[i],NULL)==0&&args[i].status==CP_OK);}for(uint64_t key=0;key<64;key++){uint64_t value;assert(cp_coordinator_get(c,key,&value)==CP_OK);assert(value==(key/16)*16+(key%16)*3);}size_t n=0;assert(cp_coordinator_scan(c,0,63,count_cb,&n)==CP_OK&&n==64);cp_coordinator_close(c);assert(cp_coordinator_open(dir,4,8,&c)==CP_OK);uint64_t value=0;cp_status status=cp_coordinator_get(c,47,&value);if(status!=CP_OK||value!=77)fprintf(stderr,"reopen key 47 status=%d value=%llu\n",status,(unsigned long long)value);assert(status==CP_OK&&value==77);cp_coordinator_close(c);}
static void test_join(void){cp_coordinator*c;assert(cp_coordinator_open("test-data",3,8,&c)==CP_OK);cp_kv l[]={{1,10},{2,20},{2,21}},r[]={{2,90},{2,91},{3,30}};cp_join_row*rows=NULL;size_t n=0;assert(cp_coordinator_join(c,l,3,r,3,&rows,&n)==CP_OK&&n==4);free(rows);cp_kv hot_l[20],hot_r[10];for(size_t i=0;i<20;i++)hot_l[i]=(cp_kv){777,i};for(size_t i=0;i<10;i++)hot_r[i]=(cp_kv){777,i+100};assert(cp_coordinator_join(c,hot_l,20,hot_r,10,&rows,&n)==CP_OK&&n==200);free(rows);assert(cp_coordinator_join_ex(c,hot_l,20,hot_r,10,0,&rows,&n)==CP_OK&&n==200);free(rows);assert(cp_coordinator_join(c,NULL,0,NULL,0,&rows,&n)==CP_OK&&n==0&&rows==NULL);cp_coordinator_close(c);}
int main(void){test_page();test_buffer_pool();test_tree_wal();test_tree_boundaries_and_updates();test_wal_io_failures();test_file_persistence();test_coordinator_storage();test_join();puts("CrashPad tests passed");return 0;}
